nagement_oidc_config)\\n        return\\n    if args.serve_limited:\\n        if any(value is None for value in values) or args.source_candidate is None:\\n            parser.error('limited start requires current installation, bundle root, trust roots and source candidate')\\n        serve_limited(identity_file=args.api_identity_file, bundle_root=args.bundle_root,\\n            trust_roots_file=args.trust_roots_file, installation_id=args.current_installation,\\n            source_candidate=args.source_candidate)\\n        return\\n    if args.source_candidate is not None:\\n        parser.error('source candidate requires explicit limited start')\\n    if any(value is not None for value in values):\\n        if any(value is None for value in values):\\n            parser.error('current installation, bundle root and trust roots are required together')\\n        report = select_current_installation(identity_file=args.api_identity_file,\\n            bundle_root=args.bundle_root, trust_roots_file=args.trust_roots_file,\\n            installation_id=args.current_installation)\\n    else:\\n        report = preflight(args.api_identity_file)\\n    print(json.dumps(report,ensure_ascii=False,indent=2))\\n\\nif __name__ == '__main__':\\n    try:\\n        main()\\n    except RestorationBlocked as exc:\\n        print(json.dumps({'outcome': 'RESTORED_HTTP_STARTUP_REJECTED', 'reason': str(exc),\\n            'apiStarted': False, 'runtimeAuthorized': False}, ensure_ascii=False), flush=True)\\n        raise SystemExit(2)\\n\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-1.txt\": \"import { useEffect, useState, type ReactNode, type FormEvent } from \\\"react\\\";\\nimport { getApiBase } from \\\"../../api/apiBase\\\";\\nimport { getAccessToken } from \\\"../../api/tenant\\\";\\nimport { loginPassword } from \\\"../../api/passwordLogin\\\";\\n\\n/** Read the server's login policy before mounting business catalog consumers. */\\nexport function LocalLoginGate({ children }: { children: ReactNode }) {\\n  const [policy, setPolicy] = useState<\\\"loading\\\" | \\\"legacy\\\" | \\\"password\\\" | \\\"error\\\">(\\\"loading\\\");\\n  const [retry, setRetry] = useState(0);\\n  const [authenticated, setAuthenticated] = useState(Boolean(getAccessToken()));\\n  const [username, setUsername] = useState(\\\"\\\");\\n  const [password, setPassword] = useState(\\\"\\\");\\n  const [busy, setBusy] = useState(false);\\n  const [error, setError] = useState(\\\"\\\");\\n  useEffect(() => {\\n    const controller = new AbortController();\\n    setPolicy(\\\"loading\\\");\\n    fetch(`${getApiBase()}/v1/auth/oidc`, { cache: \\\"no-store\\\", signal: controller.signal })\\n      .then(async (response) => {\\n        if (!response.ok) throw new Error();\\n        const config = await response.json();\\n        if (config.allowDevToken === true) setPolicy(\\\"legacy\\\");\\n        else if (config.allowDevToken === false && config.tokenUrlConfigured === true && config.grantTypes?.includes(\\\"password\\\")) setPolicy(\\\"password\\\");\\n        else throw new Error();\\n      }).catch(() => { if (!controller.signal.aborted) setPolicy(\\\"error\\\"); });\\n    return () => controller.abort();\\n  }, [retry]);\\n  useEffect(() => {\\n    const update = () => setAuthenticated(Boolean(getAccessToken()));\\n    window.addEventListener(\\\"aos-auth-updated\\\", update);\\n    return () => window.removeEventListener(\\\"aos-auth-updated\\\", update);\\n  }, []);\\n  async function submit(event: FormEvent) {\\n    event.preventDefault();\\n    if (busy) return;\\n    const submitted = password;\\n    setPassword(\\\"\\\"); setBusy(true); setError(\\\"\\\");\\n    try { await loginPassword(username, submitted); }\\n    catch (cause) { setError(cause instanceof Error ? cause.message : \\\"登录失败，请重试。\\\"); }\\n    finally { setBusy(false); }\\n  }\\n  if (policy === \\\"legacy\\\" || (policy === \\\"password\\\" && authenticated)) return <>{children}</>;\\n  return <main style={{ maxWidth: 420, margin: \\\"12vh auto\\\", padding: 24 }}>\\n    <h1>AOS 登录</h1>\\n    {policy === \\\"loading\\\" ? <p role=\\\"status\\\">正在读取登录配置…</p> : policy === \\\"error\\\" ? <>\\n      <p role=\\\"alert\\\">登录服务暂不可用，请重新读取配置。</p>\\n      <button onClick={() => setRetry((value) => value + 1)}>重试</button>\\n    </> : <form onSubmit={submit}>\\n      <p>登录后进入你有权限访问的组织与工作区。</p>\\n      <label>登录名<input autoComplete=\\\"username\\\" value={username} onChange={(event) => setUsername(event.target.value)} required disabled={busy} /></label>\\n      <label>密码<input type=\\\"password\\\" autoComplete=\\\"current-password\\\" value={password} onChange={(event) => setPassword(event.target.value)} required disabled={busy} /></label>\\n      {error && <p role=\\\"alert\\\">{error}</p>}\\n      <button type=\\\"submit\\\" disabled={busy}>{busy ? \\\"登录中…\\\" : \\\"登录\\\"}</button>\\n    </form>}\\n  </main>;\\n}\\n\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-2.txt\": \"import { getApiBase } from \\\"./apiBase\\\";\\nimport { applyMeToTenant, clearAccessToken, getTenant, setAccessToken, type MeResponse } from \\\"./tenant\\\";\\n\\n/** Original server authentication; credentials and refresh tokens never persist. */\\nexport async function loginPassword(username: string, password: string): Promise<void> {\\n  clearAccessToken();\\n  try {\\n    const response = await fetch(`${getApiBase()}/v1/auth/token`, {\\n      method: \\\"POST\\\", cache: \\\"no-store\\\",\\n      headers: { \\\"Content-Type\\\": \\\"application/json\\\" },\\n      body: JSON.stringify({ grantType: \\\"password\\\", username, password }),\\n    });\\n    if (!response.ok) throw new Error();\\n    const tokens = await response.json();\\n    if (typeof tokens.access_token !== \\\"string\\\" || !tokens.access_token.trim()) throw new Error();\\n    const tenant = getTenant();\\n    const meResponse = await fetch(`${getApiBase()}/v1/me`, {\\n      cache: \\\"no-store\\\",\\n      headers: { Authorization: `Bearer ${tokens.access_token}`, \\\"X-Org-Id\\\": tenant.orgId, \\\"X-Project-Id\\\": tenant.projectId },\\n    });\\n    if (!meResponse.ok) throw new Error();\\n    const me: MeResponse = await meResponse.json();\\n    if (!me.subject || !me.orgId || !me.projectId) throw new Error();\\n    applyMeToTenant(me);\\n    setAccessToken(tokens.access_token);\\n  } catch {\\n    clearAccessToken();\\n    throw new Error(\\\"登录失败，请核对账号、密码及工作区访问权限后重试。\\\");\\n  }\\n}\\n\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-3.txt\": \"import { afterEach, describe, expect, it, vi } from \\\"vitest\\\";\\nimport { loginPassword } from \\\"./passwordLogin\\\";\\nimport { clearAccessToken, getAccessToken, getTenant } from \\\"./tenant\\\";\\nimport { act, createElement } from \\\"react\\\";\\nimport { createRoot } from \\\"react-dom/client\\\";\\nimport { LocalLoginGate } from \\\"../components/auth/LocalLoginGate\\\";\\n\\nafterEach(() => { vi.unstubAllGlobals(); clearAccessToken(); });\\ndescribe(\\\"human password login\\\", () => {\\n  it(\\\"uses original grant and canonical me before publishing memory session\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValueOnce(new Response(JSON.stringify({ access_token: \\\"signed\\\", refresh_token: \\\"discard\\\" })))\\n      .mockResolvedValueOnce(new Response(JSON.stringify({ subject: \\\"human\\\", orgId: \\\"org-org\\\", projectId: \\\"dev-project\\\", workspaceName: \\\"真实工作区\\\", roles: [\\\"admin\\\"], markings: [], tokenKind: \\\"oidc\\\" })));\\n    vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await loginPassword(\\\"user\\\", \\\"private\\\");\\n    expect(fetch.mock.calls[0][0]).toContain(\\\"/v1/auth/token\\\");\\n    expect(JSON.parse(fetch.mock.calls[0][1].body)).toEqual({ grantType: \\\"password\\\", username: \\\"user\\\", password: \\\"private\\\" });\\n    expect(fetch.mock.calls[1][1].headers.Authorization).toBe(\\\"Bearer signed\\\");\\n    expect(getAccessToken()).toBe(\\\"signed\\\");\\n    expect(getTenant().subject).toBe(\\\"human\\\");\\n    expect(localStorage.getItem(\\\"access_token\\\")).toBeNull();\\n    expect(sessionStorage.getItem(\\\"refresh_token\\\")).toBeNull();\\n  });\\n  it(\\\"does not retry rejected credentials or publish a session\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValue(new Response(\\\"private provider detail\\\", { status: 401 }));\\n    vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(fetch).toHaveBeenCalledTimes(1);\\n    expect(getAccessToken()).toBeNull();\\n  });\\n  it(\\\"rejects incomplete token responses before fetching identity\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValue(new Response(\\\"{}\\\")); vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(fetch).toHaveBeenCalledTimes(1); expect(getAccessToken()).toBeNull();\\n  });\\n  it(\\\"does not expose an unverified session when canonical me fails\\\", async () => {\\n    const fetch = vi.fn().mockResolvedValueOnce(new Response('{\\\"access_token\\\":\\\"signed\\\"}'))\\n      .mockResolvedValueOnce(new Response(\\\"{}\\\", { status: 403 })); vi.stubGlobal(\\\"fetch\\\", fetch);\\n    await expect(loginPassword(\\\"user\\\", \\\"private\\\")).rejects.toThrow(\\\"登录失败\\\");\\n    expect(getAccessToken()).toBeNull();\\n  });\\n});\\n\\ndescribe(\\\"server login policy gate\\\", () => {\\n  async function renderPolicy(body: unknown, status = 200) {\\n    vi.stubGlobal(\\\"IS_REACT_ACT_ENVIRONMENT\\\", true);\\n    vi.stubGlobal(\\\"fetch\\\", vi.fn().mockResolvedValue(new Response(JSON.stringify(body), { status })));\\n    const container = document.createElement(\\\"div\\\");\\n    const root = createRoot(container);\\n    await act(async () => { root.render(createElement(LocalLoginGate, { children: \\\"business catalog\\\" })); });\\n    const text = container.textContent;\\n    await act(async () => root.unmount());\\n    return text;\\n  }\\n  it(\\\"preserves the explicitly enabled legacy development UI\\\", async () => {\\n    expect(await renderPolicy({ allowDevToken: true })).toContain(\\\"business catalog\\\");\\n  });\\n  it(\\\"requires human login before mounting business consumers\\\", async () => {\\n    const text = await renderPolicy({ allowDevToken: false, tokenUrlConfigured: true, grantTypes: [\\\"password\\\"] });\\n    expect(text).toContain(\\\"登录名\\\"); expect(text).not.toContain(\\\"business catalog\\\");\\n  });\\n  it(\\\"fails closed for unreadable or unsupported login configuration\\\", async () => {\\n    for (const [body, status] of [[{}, 200], [{ allowDevToken: false }, 200], [{}, 503]] as const) {\\n      const text = await renderPolicy(body, status);\\n      expect(text).toContain(\\\"登录服务暂不可用\\\"); expect(text).not.toContain(\\\"business catalog\\\");\\n    }\\n  });\\n});\\n\", \".evidence/qyh-human-login-quality-review-20261013/public-code-material-4.txt\": \"{\\n  \\\"outcome\\\": \\\"LOCAL_OIDC_READONLY_ENTRY_CODE_GREEN\\\",\\n  \\\"tests\\\": 97,\\n  \\\"failed\\\": 0,\\n  \\\"files\\\": {\\n    \\\"scripts/a0v_qyh_restored_http.py\\\": \\\"79977f32ef3645767ad4d674ac8acbf052a28e28a23926da351a8878f4ed312e\\\",\\n    \\\"services/aos-api/tests/extension_runtime/test_qyh_restored_http.py\\\": \\\"96c596b5885b20300cf33ce660efa576fb37ba2a159a99cb1da8b6dbd54d8863\\\"\\n  },\\n  \\\"logSha256\\\": \\\"b29699e63734a52d92d80734ae169221e895bd798f8ef48ca5ddcc161a6e430f\\\",\\n  \\\"defaultReadonlyPreserved\\\": true,\\n  \\\"optInLoginRoute\\\": \\\"POST /v1/auth/token\\\",\\n  \\\"businessMutationsAllowed\\\": false,\\n  \\\"liveApiIntegrated\\\": false,\\n  \\\"eightWorkshopsAccepted\\\": false,\\n  \\\"aosDatabaseWrites\\\": 0,\\n  \\\"review\\\": \\\"Exact private config; original authentication