th) -> None:\\n    _require_external_oidc()\\n    if not _port_free(8080) or not _port_free(18181):\\n        raise PreviewBlocked(\\\"HTTP_OR_SECOND_RUNTIME_PORT_OCCUPIED\\\")\\n    child_env = {k: v for k, v in os.environ.items()\\n                 if k not in {\\\"AOS_DATABASE_URL\\\", \\\"PGPASSWORD\\\", \\\"PGPASSFILE\\\"}}\\n    child = subprocess.run([sys.executable, str(Path(__file__).resolve()),\\n\", \".evidence/qyh-human-login-quality-review-20261013/scope-clarification.txt\": \"Bounded scope: management_app/serve_management_readonly are the local management-only path on18080. The original _require_external_oidc is the unchanged formal serve_limited path; it rejects localhost/http and is not claimed passed. Material app-integration.txt shows actual App providers nested inside LocalLoginGate. Original GET /v1/auth/oidc returns original public_config; entry config before app import fixes allow-dev=false and token URL. This review does not claim enterprise HTTPS, runtime Host admission, actual browser login or eight workbenches.\\n\", \".evidence/qyh-human-login-quality-review-20261013/public-policy-function-excerpt.txt\": \"\\n@router.get(\\\"/v1/auth/oidc\\\")\\ndef oidc_public_config() -> dict[str, Any]:\\n    return public_config()\\n\\n\"}}"}],"timestamp":1791828986701},{"role":"assistant","content":[{"type":"text","text":"{\"schema\":\"aos-material-review/v1\",\"request_id\":\"qyh-human-login-quality-review-20261013-r4\",\"task_id\":\"qyh-human-login-quality-review-20261013\",\"owner\":\"codex-01a107a2-e9e4-7670-bc44-1144fa9b27e2\",\"kind\":\"quality\",\"baseline\":{\"head\":\"f8cf3a41d754564cb4ff2f7e198ccf963bc8b049\",\"authority_revision\":\"AOS-001987\",\"files\":{\".evidence/qyh-human-login-quality-review-20261013/public-code-material-0.txt\":\"79977f32ef3645767ad4d674ac8acbf052a28e28a23926da351a8878f4ed312e\",\".evidence/qyh-human-login-quality-review-20261013/public-code-material-1.txt\":\"ba142f98fb73f0d2ce14a352d46e411bef77b49355d396d1a2702114f